fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Create a vector with capacity n for the column
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        // Safety: i < n and j < m assumed by problem statement
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Result will have m rows, each a vector of length n
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        // Extract the j-th column as a row in result
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}